static std::vector<std::string> g_words;

static void SetTitle(const std::string& t)
{
	SetConsoleTitleA(t.c_str());
}

static std::string Lower(std::string s)
{
	std::transform(s.begin(), s.end(), s.begin(),
		[](unsigned char c) { return (char)std::tolower(c); });
	return s;
}

static bool InDict(const std::string& w)
{
	return std::find(g_words.begin(), g_words.end(), w) != g_words.end();
}

static void UpdateTitle(const std::string& prev, const std::string& errorMsg)
{
	if (!errorMsg.empty())
	{
		SetTitle(errorMsg);
		return;
	}
	
	if (prev.empty())
		SetTitle("Word Chain - type the first word (Space/Enter to submit, Backspace to delete)");
	else
		SetTitle("Word Chain - last word: " + prev +
			" (Space/Enter to submit, Backspace to delete)");
}

int main() {
	std::istringstream iss(g_wordList);
	std::string w;
	while (iss >> w) g_words.push_back(w);
	
	std::string prev;
	std::string buf;
	std::string errorMsg;
	
	UpdateTitle(prev, errorMsg);
	
	for (;;)
	{
		int ch = _getch();
		
		if (ch == 8 || ch == 127)
		{
			if (!buf.empty())
			{
				buf.pop_back();
				std::cout << "\b \b";
			}
			errorMsg.clear();
			UpdateTitle(prev, errorMsg);
		}
		else if (ch == ' ' || ch == 13)
		{
			if (buf.empty())
			{
				errorMsg = "Empty word. Type something and press Space/Enter.";
				UpdateTitle(prev, errorMsg);
				continue;
			}
			
			std::string word = Lower(buf);
			bool ok = true;
			
			
			if (!InDict(word))
			{
				errorMsg = "Spelling error: \"" + buf +
				"\" is not a valid word. Fix it and press Space/Enter.";
				ok = false;
			}
			
			else if (!prev.empty() && word.front() != prev.back())
			{
				errorMsg = "Rule broken: must start with '" +
				std::string(1, prev.back()) +
				"'. Fix it and press Space/Enter.";
				ok = false;
			}
			
			if (!ok)
			{
				UpdateTitle(prev, errorMsg);
				continue;
			}
			
			if (ch == ' ')
				std::cout << ' ';
			else
				std::cout << '\n';
			
			prev = word;
			buf.clear();
			errorMsg.clear();
			UpdateTitle(prev, errorMsg);
		}
		else if (ch >= 32 && ch < 127)
		{
			buf.push_back((char)ch);
			std::cout << (char)ch;
			errorMsg.clear();
			UpdateTitle(prev, errorMsg);
		}
	}
	
	return 0;
}
